from rest_framework import viewsets, permissions
from .models import VaultDocument
from .serializers import VaultDocumentSerializer
from .permissions import IsVaultMember

class VaultDocumentViewSet(viewsets.ModelViewSet):
    serializer_class = VaultDocumentSerializer

    def get_queryset(self):
        if not self.request.user.is_authenticated:
            return VaultDocument.objects.none()
        return VaultDocument.objects.filter(vault__members=self.request.user)

    def get_permissions(self):
        return [permissions.IsAuthenticated(), IsVaultMember()]
